def transform(grid):
    n = len(grid)
    # The 3x3 motif is turned before being unfolded.
    if grid[0][0] == grid[0][2] == grid[2][2] and grid[1][1] == grid[0][0]:
        base = [list(row) for row in zip(*grid)]
    else:
        base = [row[::-1] for row in grid[::-1]]

    idx = [0, 1, 2, 2, 1, 0, 0, 1, 2]
    return [[base[idx[r]][idx[c]] for c in idx] for r in idx]
